import math

def get_prime_and_exponent(n):
    """Returns (p, A) such that n = p^A, or (None, None) if n is not a prime power."""
    if n <= 1:
        return (None, None)

    p = -1
    A = 0
    temp = n

    while temp > 1:
        if p == -1:
            p = temp

        # Check if p is still the only prime factor
        if temp % p != 0:
            # If we found a different prime factor, it's not a prime power
            return (None, None)

        temp //= p
        A += 1

    # If temp is 1, we successfully factored it as p^A.
    # If p was never set (only happens if n=1, handled above), return None.
    if p == -1:
        return (None, None)

    return (p, A)

def find_solutions(m_limit, n_limit):
    solutions = []
    for m in range(1, m_limit + 1):
        for n in range(1, n_limit + 1):
            X = m*m + n
            Y = m + n*n

            # Check X = p^A, A >= 2
            p_x, A_x = get_prime_and_exponent(X)
            if p_x is None or A_x < 2:
                continue

            # Check Y = p^B, B >= 2
            p_y, B_y = get_prime_and_exponent(Y)
            if p_y is None or B_y < 2:
                continue

            # Check if they share the same prime base p
            if p_x == p_y:
                p = p_x
                solutions.append((m, n, p))

    return solutions

# Task 1: Rigorously verify existing solutions
solutions_to_verify = [(2, 5, 3), (5, 2, 3)]
verification_results = {}
print("--- Verification ---")
for m, n, p in solutions_to_verify:
    X = m*m + n
    Y = m + n*n
    print(f"Checking ({m}, {n}, {p}):")

    # Check X
    is_x_power = False
    for i in range(2, 10): # Check up to 3^3 for simplicity in verification
        if X == p**i:
            is_x_power = True
            break

    # Check Y
    is_y_power = False
    for i in range(2, 10):
        if Y == p**i:
            is_y_power = True
            break

    if is_x_power and is_y_power:
        verification_results[(m, n, p)] = "Verified"
    else:
        verification_results[(m, n, p)] = "Failed"

print("\nVerification Summary:", verification_results)

# Task 2: Systematic search for m, n <= 10
print("\n--- Systematic Search (m, n <= 10) ---")
new_solutions = find_solutions(10, 10)
print("Found solutions:", new_solutions)

